const bookPages = dv.pages('"5 - Books"').where(p => p.title);
const container = this.container;

const style = document.createElement("style");
style.textContent = `
 .book-table {
 width: 100%;
 border-collapse: separate;
 border-spacing: 0;
 font-family: inherit;
 margin-top: 0.5rem;
 font-size: 14px;
 }
 .book-table th {
 background: rgba(255, 255, 255, 0.03);
 color: var(--text-muted, #9ca3af);
 padding: 10px 14px;
 border-bottom: 1px solid rgba(255, 255, 255, 0.08);
 font-weight: 600;
 text-align: left;
 font-size: 12px;
 text-transform: uppercase;
 letter-spacing: 0.05em;
 }
 .book-table th:first-child,
 .book-table td:first-child {
 width: 120px; /* Было 100px */
 text-align: center;
 }
 .book-table td {
 padding: 12px 14px;
 border-bottom: 1px solid rgba(255, 255, 255, 0.05);
 color: var(--text-normal, #e5e7eb);
 vertical-align: middle;
 }
 .book-table tr {
 transition: background-color 0.15s ease;
 }
 .book-table tr:hover {
 background: rgba(139, 92, 246, 0.04) !important;
 }
 .filter-container {
 background: rgba(0, 0, 0, 0.15);
 border-radius: 10px;
 padding: 0.8rem 1rem;
 margin-bottom: 1.5rem;
 border: 1px solid rgba(255, 255, 255, 0.08);
 display: flex;
 gap: 0.8rem;
 align-items: center;
 flex-wrap: wrap;
 }
 .filter-select, .filter-search {
 padding: 8px 12px;
 border-radius: 8px;
 border: 1px solid rgba(255, 255, 255, 0.12);
 background: var(--background-secondary, #1e1e24);
 color: var(--text-normal, #e5e7eb);
 font-size: 13px;
 outline: none;
 transition: all 0.2s ease;
 height: 38px;
 box-sizing: border-box;
 font-family: inherit;
 }
 .filter-select:hover, .filter-search:focus {
 border-color: rgba(167, 139, 250, 0.5);
 box-shadow: 0 0 0 2px rgba(139, 92, 246, 0.15);
 }
 .filter-search {
 flex: 1;
 min-width: 220px;
 }
 .book-title-link {
 color: var(--text-normal, #f3f4f6);
 text-decoration: none;
 font-weight: 600;
 font-size: 15px;
 transition: color 0.2s;
 line-height: 1.3;
 }
 .book-title-link:hover {
 color: #a78bfa;
 }
 .book-meta-text {
 font-size: 12px;
 color: var(--text-muted, #9ca3af);
 margin-top: 4px;
 }
 .status-dropdown {
 padding: 4px 8px;
 border-radius: 6px;
 font-size: 12px;
 font-weight: 600;
 border: 1px solid transparent;
 outline: none;
 cursor: pointer;
 transition: all 0.2s;
 width: 120px;
 text-align: center;
 height: 32px;
 box-sizing: border-box;
 font-family: inherit;
 }

 .book-cover-img {
 width: 80px;
 height: 120px;
 border-radius: 6px;
 object-fit: cover;
 box-shadow: 0 3px 8px rgba(0,0,0,0.25);
 border: 1px solid rgba(255, 255, 255, 0.08);
 transition: transform 0.2s, box-shadow 0.2s;
 cursor: pointer;
 display: inline-block;
 }
 .book-cover-img:hover {
